mapper.select:
select info.id trackId, info.album_id, info.track_title, info.cover_url, info.media_duration, info.status, max(if(stat.stat_type = '0701', stat.stat_num ,0)) playStatNum, max(if(stat.stat_type = '0702', stat.stat_num ,0)) collectStatNum, max(if(stat.stat_type = '0703', stat.stat_num ,0)) praiseStatNum, max(if(stat.stat_type = '0704', stat.stat_num ,0)) commentStatNum from tingshu_album.track_info as info inner join tingshu_album.track_stat stat on stat.track_id = info.id and stat.is_deleted = 0
info.track_title like concat('%',#{vo.trackTitle},'%')
and info.status = #{vo.status}
and info.user_id = #{vo.userId}
and info.is_deleted = 0
group by info.id order by info.id desc
